"""A shopping cart module supporting item management and discount-based pricing."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum, auto


class ItemNotFoundError(Exception):
    """Raised when an operation references a product not present in the cart."""

    def __init__(self, product_name: str) -> None:
        self.product_name = product_name
        super().__init__(f"No item named '{product_name}' exists in the cart.")


class DuplicateItemError(Exception):
    """Raised when attempting to add a product that already exists in the cart."""

    def __init__(self, product_name: str) -> None:
        self.product_name = product_name
        super().__init__(
            f"Item '{product_name}' is already in the cart. "
            "Use update_item_quantity() to change its quantity instead."
        )


class InvalidUnitPriceError(ValueError):
    """Raised when a unit price is not a positive number."""

    def __init__(self, unit_price: float) -> None:
        self.unit_price = unit_price
        super().__init__(f"Unit price must be positive, got {unit_price!r}.")


class InvalidQuantityError(ValueError):
    """Raised when a quantity is not a positive integer."""

    def __init__(self, quantity: int) -> None:
        self.quantity = quantity
        super().__init__(f"Quantity must be a positive integer, got {quantity!r}.")


class InvalidDiscountPercentageError(ValueError):
    """Raised when a discount percentage falls outside the valid 0-100 range."""

    def __init__(self, discount_percentage: float) -> None:
        self.discount_percentage = discount_percentage
        super().__init__(
            f"Discount percentage must be between 0 and 100, got {discount_percentage!r}."
        )


class InvalidFlatDiscountError(ValueError):
    """Raised when a flat discount amount is negative."""

    def __init__(self, discount_amount: float) -> None:
        self.discount_amount = discount_amount
        super().__init__(f"Flat discount amount cannot be negative, got {discount_amount!r}.")


class EmptyCartError(Exception):
    """Raised when an operation requires a non-empty cart."""

    def __init__(self) -> None:
        super().__init__("The cart is empty.")


@dataclass(frozen=True)
class CartItem:
    """An immutable record of a single line item within the shopping cart."""

    product_name: str
    unit_price: float
    quantity: int

    @property
    def line_total(self) -> float:
        """Return the total cost of this line item (unit price times quantity)."""
        return self.unit_price * self.quantity


class DiscountType(Enum):
    """The two supported discount strategies."""

    PERCENTAGE = auto()
    FLAT_AMOUNT = auto()


@dataclass(frozen=True)
class Discount:
    """An immutable discount to be applied to a cart's subtotal."""

    discount_type: DiscountType
    value: float


class ShoppingCart:
    """A shopping cart that tracks items and computes discounted totals.

    Items are keyed by product name, so each product may appear only once;
    callers should adjust quantity via `update_item_quantity` rather than
    re-adding the same product.
    """

    def __init__(self) -> None:
        """Initialize an empty shopping cart with no active discount."""
        self._items_by_product_name: dict[str, CartItem] = {}
        self._active_discount: Discount | None = None

    def add_item(self, product_name: str, unit_price: float, quantity: int) -> None:
        """Add a new product line item to the cart.

        Raises:
            DuplicateItemError: If the product is already in the cart.
            InvalidUnitPriceError: If unit_price is not positive.
            InvalidQuantityError: If quantity is not a positive integer.
        """
        if product_name in self._items_by_product_name:
            raise DuplicateItemError(product_name)
        self._validate_unit_price(unit_price)
        self._validate_quantity(quantity)

        self._items_by_product_name[product_name] = CartItem(
            product_name=product_name, unit_price=unit_price, quantity=quantity
        )

    def remove_item(self, product_name: str) -> None:
        """Remove a product line item from the cart entirely.

        Raises:
            ItemNotFoundError: If the product is not in the cart.
        """
        self._get_existing_item(product_name)
        del self._items_by_product_name[product_name]

    def update_item_quantity(self, product_name: str, new_quantity: int) -> None:
        """Update the quantity of an existing product line item.

        Raises:
            ItemNotFoundError: If the product is not in the cart.
            InvalidQuantityError: If new_quantity is not a positive integer.
        """
        existing_item = self._get_existing_item(product_name)
        self._validate_quantity(new_quantity)

        self._items_by_product_name[product_name] = CartItem(
            product_name=existing_item.product_name,
            unit_price=existing_item.unit_price,
            quantity=new_quantity,
        )

    def list_items(self) -> list[CartItem]:
        """Return a list of all items currently in the cart."""
        return list(self._items_by_product_name.values())

    def calculate_subtotal(self) -> float:
        """Calculate the total cost of all items before any discount is applied."""
        return sum(item.line_total for item in self._items_by_product_name.values())

    def apply_percentage_discount(self, discount_percentage: float) -> None:
        """Apply a percentage-based discount (0-100) to the cart's subtotal.

        Replaces any previously applied discount.

        Raises:
            InvalidDiscountPercentageError: If discount_percentage is outside 0-100.
        """
        if not 0 <= discount_percentage <= 100:
            raise InvalidDiscountPercentageError(discount_percentage)

        self._active_discount = Discount(
            discount_type=DiscountType.PERCENTAGE, value=discount_percentage
        )

    def apply_flat_discount(self, discount_amount: float) -> None:
        """Apply a flat, fixed-amount discount to the cart's subtotal.

        Replaces any previously applied discount. The discount is capped at
        the subtotal when the total is calculated, so the final total never
        goes negative.

        Raises:
            InvalidFlatDiscountError: If discount_amount is negative.
        """
        if discount_amount < 0:
            raise InvalidFlatDiscountError(discount_amount)

        self._active_discount = Discount(discount_type=DiscountType.FLAT_AMOUNT, value=discount_amount)

    def remove_discount(self) -> None:
        """Remove any currently active discount from the cart."""
        self._active_discount = None

    def calculate_total(self) -> float:
        """Calculate the final total after applying any active discount."""
        subtotal = self.calculate_subtotal()
        discount_amount = self._calculate_discount_amount(subtotal)
        return max(subtotal - discount_amount, 0.0)

    def clear(self) -> None:
        """Remove all items and any active discount from the cart."""
        self._items_by_product_name.clear()
        self._active_discount = None

    def _calculate_discount_amount(self, subtotal: float) -> float:
        """Compute the absolute discount amount for the given subtotal."""
        if self._active_discount is None:
            return 0.0

        if self._active_discount.discount_type is DiscountType.PERCENTAGE:
            return subtotal * (self._active_discount.value / 100)

        return min(self._active_discount.value, subtotal)

    def _get_existing_item(self, product_name: str) -> CartItem:
        """Look up an item by product name, raising if it is not present."""
        try:
            return self._items_by_product_name[product_name]
        except KeyError:
            raise ItemNotFoundError(product_name) from None

    @staticmethod
    def _validate_unit_price(unit_price: float) -> None:
        """Ensure a unit price is a positive number."""
        if unit_price <= 0:
            raise InvalidUnitPriceError(unit_price)

    @staticmethod
    def _validate_quantity(quantity: int) -> None:
        """Ensure a quantity is a positive integer."""
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise InvalidQuantityError(quantity)
